#include "space_invaders/game.h"
#include <assert.h>
int main(void) { Game g, same; game_init_seed(&g, 42); game_init_seed(&same, 42); assert(g.seed == same.seed && g.player == 22 && g.lives == 3 && g.credits == 3 && g.room == 1 && g.ante == 1 && g.blind_target == 5 && g.room_type == ROOM_COMBAT); g.score = 4; g.room_type = ROOM_ELITE; g.alien = g.player; g.bullet = g.alien_row; game_step(&g); assert(g.score == 5 && g.upgrade_offer && g.paused && g.relics == 1 && g.credits == 6 && g.blind_target == 10); game_choose_upgrade(&g, 2); assert(!g.upgrade_offer && !g.paused && g.lives == 4 && g.credits == 3); g.room = 10; g.alien_hp = 1; g.score = 49; g.alien = g.player; g.bullet = g.alien_row; game_step(&g); assert(g.won && !g.over); g.over = true; game_restart(&g); assert(!g.over && !g.won && !g.paused && g.lives == 3 && g.room == 1 && g.seed == 42 && g.relics == 0); return 0; }
